package com.campusfest.backend.judging;
import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class JudgingController{private final JudgingService service;public JudgingController(JudgingService s){service=s;}@PostMapping("/competitions/{id}/criteria")@PreAuthorize("hasAnyRole('ORGANIZER','ADMIN')")public CriterionResponse add(@PathVariable Long id,@Valid @RequestBody CriterionRequest r,Authentication a){return service.addCriterion(id,r,a.getName());}@GetMapping("/competitions/{id}/criteria")public List<CriterionResponse> criteria(@PathVariable Long id){return service.criteria(id);}@PostMapping("/competitions/{id}/judges/{judgeId}")@PreAuthorize("hasAnyRole('ORGANIZER','ADMIN')")public JudgeAssignmentResponse assign(@PathVariable Long id,@PathVariable Long judgeId,Authentication a){return service.assign(id,judgeId,a.getName());}@GetMapping("/competitions/{id}/judges")public List<JudgeAssignmentResponse> judges(@PathVariable Long id){return service.assignments(id);}@GetMapping("/judging/my-competitions")@PreAuthorize("hasRole('JUDGE')")public List<JudgeAssignmentResponse> mine(Authentication a){return service.myCompetitions(a.getName());}@PostMapping("/judging/competitions/{id}/evaluations")@PreAuthorize("hasRole('JUDGE')")public EvaluationResponse submit(@PathVariable Long id,@Valid @RequestBody EvaluationRequest r,Authentication a){return service.submit(id,r,a.getName());}@GetMapping("/competitions/{id}/results")@PreAuthorize("hasAnyRole('ORGANIZER','ADMIN','JUDGE')")public List<EvaluationResponse> results(@PathVariable Long id){return service.results(id);}}
